20260212175338	{"create table if not exists public.employee_sessions (\n  id uuid primary key default gen_random_uuid(),\n  employee_id uuid not null references public.employees(id) on delete cascade,\n  token text not null unique,\n  expires_at timestamptz not null,\n  created_at timestamptz not null default now()\n);\n\ncreate index if not exists idx_employee_sessions_token on public.employee_sessions(token);\ncreate index if not exists idx_employee_sessions_employee_id on public.employee_sessions(employee_id);\ncreate index if not exists idx_employee_sessions_expires_at on public.employee_sessions(expires_at);\n\nalter table public.employee_sessions enable row level security;"}	create_employee_sessions_table	rohan5250ssbj@gmail.com	\N	\N
20260213081434	{"create or replace function public._apply_employee_task_status_delta(\n  p_employee_id uuid,\n  p_old_status text,\n  p_new_status text\n)\nreturns void\nlanguage sql\nas $$\n  update public.employees\n  set\n    pending_tasks = greatest(\n      0,\n      coalesce(pending_tasks, 0)\n      + case when p_new_status = 'pending' then 1 else 0 end\n      - case when p_old_status = 'pending' then 1 else 0 end\n    ),\n    in_progress_tasks = greatest(\n      0,\n      coalesce(in_progress_tasks, 0)\n      + case when p_new_status = 'in_progress' then 1 else 0 end\n      - case when p_old_status = 'in_progress' then 1 else 0 end\n    ),\n    completed_tasks = greatest(\n      0,\n      coalesce(completed_tasks, 0)\n      + case when p_new_status = 'completed' then 1 else 0 end\n      - case when p_old_status = 'completed' then 1 else 0 end\n    ),\n    updated_at = now()\n  where id = p_employee_id;\n$$;\n\ncreate or replace function public.handle_task_assignment_counter_delta()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  v_old_status text;\n  v_new_status text;\nbegin\n  if tg_op = 'INSERT' then\n    select status into v_new_status\n    from public.tasks\n    where id = new.task_id;\n\n    perform public._apply_employee_task_status_delta(new.employee_id, null, v_new_status);\n    return null;\n  end if;\n\n  if tg_op = 'DELETE' then\n    select status into v_old_status\n    from public.tasks\n    where id = old.task_id;\n\n    perform public._apply_employee_task_status_delta(old.employee_id, v_old_status, null);\n    return null;\n  end if;\n\n  if old.employee_id is distinct from new.employee_id\n     or old.task_id is distinct from new.task_id then\n    select status into v_old_status\n    from public.tasks\n    where id = old.task_id;\n\n    select status into v_new_status\n    from public.tasks\n    where id = new.task_id;\n\n    perform public._apply_employee_task_status_delta(old.employee_id, v_old_status, null);\n    perform public._apply_employee_task_status_delta(new.employee_id, null, v_new_status);\n  end if;\n\n  return null;\nend;\n$$;\n\ndrop trigger if exists trg_task_assignment_counter_delta on public.task_assignments;\ncreate trigger trg_task_assignment_counter_delta\nafter insert or update or delete on public.task_assignments\nfor each row\nexecute function public.handle_task_assignment_counter_delta();\n\ncreate or replace function public.handle_task_status_counter_delta()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if old.status is not distinct from new.status then\n    return null;\n  end if;\n\n  update public.employees e\n  set\n    pending_tasks = greatest(\n      0,\n      coalesce(e.pending_tasks, 0)\n      + case when new.status = 'pending' then a.cnt else 0 end\n      - case when old.status = 'pending' then a.cnt else 0 end\n    ),\n    in_progress_tasks = greatest(\n      0,\n      coalesce(e.in_progress_tasks, 0)\n      + case when new.status = 'in_progress' then a.cnt else 0 end\n      - case when old.status = 'in_progress' then a.cnt else 0 end\n    ),\n    completed_tasks = greatest(\n      0,\n      coalesce(e.completed_tasks, 0)\n      + case when new.status = 'completed' then a.cnt else 0 end\n      - case when old.status = 'completed' then a.cnt else 0 end\n    ),\n    updated_at = now()\n  from (\n    select employee_id, count(*)::int as cnt\n    from public.task_assignments\n    where task_id = new.id\n    group by employee_id\n  ) a\n  where e.id = a.employee_id;\n\n  return null;\nend;\n$$;\n\ndrop trigger if exists trg_task_status_counter_delta on public.tasks;\ncreate trigger trg_task_status_counter_delta\nafter update of status on public.tasks\nfor each row\nexecute function public.handle_task_status_counter_delta();\n\nupdate public.employees e\nset\n  pending_tasks = coalesce(src.pending_tasks, 0),\n  in_progress_tasks = coalesce(src.in_progress_tasks, 0),\n  completed_tasks = coalesce(src.completed_tasks, 0),\n  updated_at = now()\nfrom (\n  select\n    e2.id as employee_id,\n    count(*) filter (where t.status = 'pending')::int as pending_tasks,\n    count(*) filter (where t.status = 'in_progress')::int as in_progress_tasks,\n    count(*) filter (where t.status = 'completed')::int as completed_tasks\n  from public.employees e2\n  left join public.task_assignments ta on ta.employee_id = e2.id\n  left join public.tasks t on t.id = ta.task_id\n  group by e2.id\n) src\nwhere e.id = src.employee_id;"}	task_counter_triggers	rohan5250ssbj@gmail.com	\N	\N
20260217164015	{"-- Remove redundant indexes that duplicate unique constraints or composite-prefix indexes\n\n-- Duplicates existing unique constraint index on employee_sessions(token)\ndrop index if exists public.idx_employee_sessions_token;\n\n-- Duplicates existing unique constraint index on task_assignments(task_id, employee_id)\ndrop index if exists public.idx_task_assignments_task_employee;\n\n-- Duplicate comments index on same key columns; keep idx_task_comments_task_created\ndrop index if exists public.idx_task_comments_task_id_created_at;\n\n-- Redundant to unique constraint-backed indexes on employees\ndrop index if exists public.idx_employees_username;\ndrop index if exists public.idx_employees_employee_id;\n\n-- Redundant to composite indexes with same leading column\ndrop index if exists public.idx_task_assignments_employee_id;\ndrop index if exists public.idx_task_attachments_task_id;\ndrop index if exists public.idx_task_subtasks_task_id;"}	cleanup_redundant_indexes_20260217	rohan5250ssbj@gmail.com	\N	\N
20260217164028	{"drop index if exists public.idx_employee_sessions_employee_id;"}	cleanup_redundant_employee_sessions_index_20260217	rohan5250ssbj@gmail.com	\N	\N
20260213081930	{"create or replace function public.handle_task_subtasks_status_sync()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  v_task_id uuid;\n  v_total_subtasks int;\n  v_completed_subtasks int;\n  v_next_status text;\nbegin\n  v_task_id := coalesce(new.task_id, old.task_id);\n\n  if v_task_id is null then\n    return null;\n  end if;\n\n  select count(*)::int into v_total_subtasks\n  from public.task_subtasks\n  where task_id = v_task_id;\n\n  if v_total_subtasks <= 0 then\n    return null;\n  end if;\n\n  select count(*)::int into v_completed_subtasks\n  from public.task_subtasks\n  where task_id = v_task_id\n    and is_completed = true;\n\n  if v_completed_subtasks = v_total_subtasks then\n    v_next_status := 'completed';\n  else\n    v_next_status := 'in_progress';\n  end if;\n\n  update public.tasks\n  set\n    status = v_next_status,\n    updated_at = now()\n  where id = v_task_id\n    and status is distinct from v_next_status;\n\n  return null;\nend;\n$$;\n\ndrop trigger if exists trg_task_subtasks_status_sync on public.task_subtasks;\ncreate trigger trg_task_subtasks_status_sync\nafter insert or update or delete on public.task_subtasks\nfor each row\nexecute function public.handle_task_subtasks_status_sync();\n\nupdate public.tasks t\nset\n  status = case\n    when agg.total_subtasks > 0 and agg.completed_subtasks = agg.total_subtasks then 'completed'\n    when agg.total_subtasks > 0 then 'in_progress'\n    else t.status\n  end,\n  updated_at = now()\nfrom (\n  select\n    task_id,\n    count(*)::int as total_subtasks,\n    count(*) filter (where is_completed = true)::int as completed_subtasks\n  from public.task_subtasks\n  group by task_id\n) agg\nwhere t.id = agg.task_id\n  and agg.total_subtasks > 0\n  and t.status is distinct from case\n    when agg.completed_subtasks = agg.total_subtasks then 'completed'\n    else 'in_progress'\n  end;"}	subtask_status_triggers	rohan5250ssbj@gmail.com	\N	\N
20260213083818	{"create or replace function public.handle_task_delete_counter_delta()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  update public.employees e\n  set\n    pending_tasks = greatest(\n      0,\n      coalesce(e.pending_tasks, 0)\n      - case when old.status = 'pending' then a.cnt else 0 end\n    ),\n    in_progress_tasks = greatest(\n      0,\n      coalesce(e.in_progress_tasks, 0)\n      - case when old.status = 'in_progress' then a.cnt else 0 end\n    ),\n    completed_tasks = greatest(\n      0,\n      coalesce(e.completed_tasks, 0)\n      - case when old.status = 'completed' then a.cnt else 0 end\n    ),\n    updated_at = now()\n  from (\n    select employee_id, count(*)::int as cnt\n    from public.task_assignments\n    where task_id = old.id\n    group by employee_id\n  ) a\n  where e.id = a.employee_id;\n\n  return old;\nend;\n$$;\n\ndrop trigger if exists trg_task_delete_counter_delta on public.tasks;\ncreate trigger trg_task_delete_counter_delta\nbefore delete on public.tasks\nfor each row\nexecute function public.handle_task_delete_counter_delta();\n\nupdate public.employees e\nset\n  pending_tasks = coalesce(src.pending_tasks, 0),\n  in_progress_tasks = coalesce(src.in_progress_tasks, 0),\n  completed_tasks = coalesce(src.completed_tasks, 0),\n  updated_at = now()\nfrom (\n  select\n    e2.id as employee_id,\n    count(*) filter (where t.status = 'pending')::int as pending_tasks,\n    count(*) filter (where t.status = 'in_progress')::int as in_progress_tasks,\n    count(*) filter (where t.status = 'completed')::int as completed_tasks\n  from public.employees e2\n  left join public.task_assignments ta on ta.employee_id = e2.id\n  left join public.tasks t on t.id = ta.task_id\n  group by e2.id\n) src\nwhere e.id = src.employee_id;"}	task_delete_counter_fix	rohan5250ssbj@gmail.com	\N	\N
20260213180015	{"-- Task comments for admin + assigned employees\n\ncreate table if not exists public.task_comments (\n  id uuid primary key default gen_random_uuid(),\n  task_id uuid not null references public.tasks(id) on delete cascade,\n  author_type text not null check (author_type in ('admin', 'employee')),\n  author_name text not null,\n  author_avatar_url text,\n  employee_id uuid references public.employees(id) on delete set null,\n  profile_id uuid references public.profiles(id) on delete set null,\n  comment_text text not null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint task_comments_comment_text_not_blank check (length(btrim(comment_text)) > 0)\n);\n\ncreate index if not exists idx_task_comments_task_id_created_at\n  on public.task_comments(task_id, created_at desc);\n\ncreate or replace function public.handle_task_comments_updated_at()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  new.updated_at := now();\n  return new;\nend;\n$$;\n\ndrop trigger if exists trg_task_comments_updated_at on public.task_comments;\ncreate trigger trg_task_comments_updated_at\nbefore update on public.task_comments\nfor each row\nexecute function public.handle_task_comments_updated_at();"}	task_comments	rohan5250ssbj@gmail.com	\N	\N
20260216141124	{"-- Improve real-time dashboard performance and employee session lookups\n\ncreate unique index if not exists idx_employee_sessions_token\n  on public.employee_sessions(token);\n\ncreate index if not exists idx_employee_sessions_employee_expires\n  on public.employee_sessions(employee_id, expires_at desc);\n\ncreate index if not exists idx_employee_sessions_expires_at\n  on public.employee_sessions(expires_at);\n\ncreate unique index if not exists idx_task_assignments_task_employee\n  on public.task_assignments(task_id, employee_id);\n\ncreate index if not exists idx_task_assignments_employee_assigned_at\n  on public.task_assignments(employee_id, assigned_at desc);\n\ncreate index if not exists idx_tasks_status_created_at\n  on public.tasks(status, created_at desc);\n\ncreate or replace function public.cleanup_expired_employee_sessions()\nreturns void\nlanguage sql\nas $$\n  delete from public.employee_sessions\n  where expires_at <= now();\n$$;"}	employee_session_and_task_indexes	rohan5250ssbj@gmail.com	\N	\N
20260216152317	{"create index if not exists idx_task_attachments_task_uploaded\n  on public.task_attachments(task_id, uploaded_at desc);\n\ncreate index if not exists idx_task_subtasks_task_created\n  on public.task_subtasks(task_id, created_at asc);\n\ncreate index if not exists idx_task_comments_task_created\n  on public.task_comments(task_id, created_at asc);"}	task_detail_latency_indexes	rohan5250ssbj@gmail.com	\N	\N
20260216164030	{"-- Optimize subtask->task status sync trigger for lower latency\n-- - Avoids recounting when UPDATE does not change completion state\n-- - Uses a single aggregate query instead of two separate counts\n\ncreate or replace function public.handle_task_subtasks_status_sync()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  v_task_id uuid;\n  v_total_subtasks int;\n  v_completed_subtasks int;\n  v_next_status text;\nbegin\n  if tg_op = 'UPDATE'\n     and new.task_id is not distinct from old.task_id\n     and new.is_completed is not distinct from old.is_completed then\n    return null;\n  end if;\n\n  v_task_id := coalesce(new.task_id, old.task_id);\n\n  if v_task_id is null then\n    return null;\n  end if;\n\n  select\n    count(*)::int,\n    count(*) filter (where is_completed = true)::int\n  into v_total_subtasks, v_completed_subtasks\n  from public.task_subtasks\n  where task_id = v_task_id;\n\n  -- Preserve existing behavior: if no subtasks exist, do not force status.\n  if v_total_subtasks <= 0 then\n    return null;\n  end if;\n\n  if v_completed_subtasks = v_total_subtasks then\n    v_next_status := 'completed';\n  else\n    v_next_status := 'in_progress';\n  end if;\n\n  update public.tasks\n  set\n    status = v_next_status,\n    updated_at = now()\n  where id = v_task_id\n    and status is distinct from v_next_status;\n\n  return null;\nend;\n$$;"}	subtask_status_sync_perf	rohan5250ssbj@gmail.com	\N	\N
20260217164308	{"create extension if not exists pg_cron;\n\ndo $migration$\ndeclare\n  v_job_id bigint;\nbegin\n  for v_job_id in\n    select jobid\n    from cron.job\n    where jobname = 'cleanup_expired_employee_sessions_every_15m'\n  loop\n    perform cron.unschedule(v_job_id);\n  end loop;\n\n  perform cron.schedule(\n    'cleanup_expired_employee_sessions_every_15m',\n    '*/15 * * * *',\n    $cmd$select public.cleanup_expired_employee_sessions();$cmd$\n  );\nend\n$migration$;"}	schedule_cleanup_expired_employee_sessions_20260217	rohan5250ssbj@gmail.com	\N	\N
20260218045052	{"-- Security helper: admin check based on profiles.role (server-controlled)\ncreate or replace function public.is_admin()\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nset row_security = off\nas $$\n  select exists (\n    select 1\n    from public.profiles p\n    where p.id = auth.uid()\n      and p.role = 'admin'\n  );\n$$;\n\n-- Fix insecure policies on profiles\nalter policy \\"Admins can view all profiles\\" on public.profiles\n  using (public.is_admin());\n\nalter policy \\"Admins can update all profiles\\" on public.profiles\n  using (public.is_admin());\n\n-- Enable RLS on missing tables\nalter table public.task_comments enable row level security;\nalter table public.task_subtasks enable row level security;\n\n-- Task comments policies\ncreate policy \\"Anyone can view task comments\\"\n  on public.task_comments for select\n  using (true);\n\ncreate policy \\"Admin can insert task comments\\"\n  on public.task_comments for insert\n  with check (public.is_admin());\n\ncreate policy \\"Admin can update task comments\\"\n  on public.task_comments for update\n  using (public.is_admin());\n\ncreate policy \\"Admin can delete task comments\\"\n  on public.task_comments for delete\n  using (public.is_admin());\n\n-- Task subtasks policies\ncreate policy \\"Anyone can view task subtasks\\"\n  on public.task_subtasks for select\n  using (true);\n\ncreate policy \\"Admin can insert task subtasks\\"\n  on public.task_subtasks for insert\n  with check (public.is_admin());\n\ncreate policy \\"Admin can update task subtasks\\"\n  on public.task_subtasks for update\n  using (public.is_admin());\n\ncreate policy \\"Admin can delete task subtasks\\"\n  on public.task_subtasks for delete\n  using (public.is_admin());\n"}	fix_rls_and_admin_policy_roles	rohan5250ssbj@gmail.com	\N	\N
20260218045211	{"-- Prevent non-admin role changes in profiles\nalter policy \\"Users can update their own profile\\" on public.profiles\n  with check (\n    auth.uid() = id\n    and role = (\n      select p.role from public.profiles p where p.id = auth.uid()\n    )\n  );\n\n-- Column-level safety: disallow role updates for general roles\nrevoke update (role) on table public.profiles from public;\nrevoke update (role) on table public.profiles from authenticated;"}	lockdown_profiles_role_updates	rohan5250ssbj@gmail.com	\N	\N
20260218065901	{"-- Email outbox + notification plumbing for employee onboarding and task alerts.\n\nalter table public.employees\n  add column if not exists must_change_password boolean not null default false,\n  add column if not exists password_set_at timestamptz;\n\ncreate table if not exists public.email_outbox (\n  id uuid primary key default gen_random_uuid(),\n  event_type text not null check (event_type in ('employee_created', 'task_assigned', 'task_due')),\n  recipient_email text not null,\n  payload jsonb not null default '{}'::jsonb,\n  status text not null default 'pending' check (status in ('pending', 'processing', 'sent', 'failed')),\n  scheduled_for timestamptz not null default timezone('utc'::text, now()),\n  attempt_count int not null default 0,\n  last_error text,\n  sent_at timestamptz,\n  locked_at timestamptz,\n  dedupe_key text not null unique,\n  provider_message_id text,\n  created_at timestamptz not null default timezone('utc'::text, now()),\n  updated_at timestamptz not null default timezone('utc'::text, now())\n);\n\ncreate index if not exists idx_email_outbox_status_schedule\n  on public.email_outbox(status, scheduled_for);\n\ncreate index if not exists idx_email_outbox_event_status\n  on public.email_outbox(event_type, status);\n\ncreate index if not exists idx_email_outbox_locked_at\n  on public.email_outbox(locked_at);\n\ncreate or replace function public.set_email_outbox_updated_at()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  new.updated_at = timezone('utc'::text, now());\n  return new;\nend;\n$$;\n\ndrop trigger if exists trg_email_outbox_updated_at on public.email_outbox;\ncreate trigger trg_email_outbox_updated_at\nbefore update on public.email_outbox\nfor each row\nexecute function public.set_email_outbox_updated_at();\n\ncreate or replace function public.enqueue_task_assignment_email()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_task record;\n  v_employee record;\n  v_due_epoch bigint;\nbegin\n  select\n    t.id,\n    t.task_name,\n    t.description,\n    t.priority,\n    t.due_date\n  into v_task\n  from public.tasks t\n  where t.id = new.task_id;\n\n  select\n    e.id,\n    e.name,\n    e.email\n  into v_employee\n  from public.employees e\n  where e.id = new.employee_id;\n\n  if v_task.id is null or v_employee.id is null or coalesce(v_employee.email, '') = '' then\n    return new;\n  end if;\n\n  v_due_epoch := case\n    when v_task.due_date is null then 0\n    else extract(epoch from v_task.due_date)::bigint\n  end;\n\n  insert into public.email_outbox (\n    event_type,\n    recipient_email,\n    payload,\n    dedupe_key\n  )\n  values (\n    'task_assigned',\n    lower(v_employee.email),\n    jsonb_build_object(\n      'task_id', v_task.id,\n      'task_name', v_task.task_name,\n      'task_description', coalesce(v_task.description, ''),\n      'priority', coalesce(v_task.priority, 'medium'),\n      'due_date', v_task.due_date,\n      'employee_id', v_employee.id,\n      'employee_name', coalesce(v_employee.name, 'Employee')\n    ),\n    concat(\n      'task_assigned:',\n      v_task.id::text,\n      ':',\n      v_employee.id::text,\n      ':',\n      coalesce(extract(epoch from new.assigned_at)::bigint, 0)::text,\n      ':',\n      v_due_epoch::text\n    )\n  )\n  on conflict (dedupe_key) do nothing;\n\n  return new;\nend;\n$$;\n\ndrop trigger if exists trg_task_assignment_email_outbox on public.task_assignments;\ncreate trigger trg_task_assignment_email_outbox\nafter insert on public.task_assignments\nfor each row\nexecute function public.enqueue_task_assignment_email();\n\ncreate or replace function public.enqueue_due_task_emails()\nreturns int\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_inserted int := 0;\nbegin\n  with due_candidates as (\n    select\n      t.id as task_id,\n      t.task_name,\n      coalesce(t.description, '') as task_description,\n      coalesce(t.priority, 'medium') as priority,\n      t.due_date,\n      e.id as employee_id,\n      coalesce(e.name, 'Employee') as employee_name,\n      lower(e.email) as recipient_email,\n      concat(\n        'task_due:',\n        t.id::text,\n        ':',\n        e.id::text,\n        ':',\n        extract(epoch from t.due_date)::bigint::text\n      ) as dedupe_key\n    from public.tasks t\n    join public.task_assignments ta on ta.task_id = t.id\n    join public.employees e on e.id = ta.employee_id\n    where t.due_date is not null\n      and t.due_date <= timezone('utc'::text, now())\n      and t.status <> 'completed'\n      and coalesce(e.email, '') <> ''\n  ),\n  inserted as (\n    insert into public.email_outbox (\n      event_type,\n      recipient_email,\n      payload,\n      dedupe_key\n    )\n    select\n      'task_due',\n      due_candidates.recipient_email,\n      jsonb_build_object(\n        'task_id', due_candidates.task_id,\n        'task_name', due_candidates.task_name,\n        'task_description', due_candidates.task_description,\n        'priority', due_candidates.priority,\n        'due_date', due_candidates.due_date,\n        'employee_id', due_candidates.employee_id,\n        'employee_name', due_candidates.employee_name\n      ),\n      due_candidates.dedupe_key\n    from due_candidates\n    on conflict (dedupe_key) do nothing\n    returning 1\n  )\n  select count(*)::int into v_inserted from inserted;\n\n  return coalesce(v_inserted, 0);\nend;\n$$;\n\ncreate or replace function public.claim_email_outbox_jobs(p_limit int default 25)\nreturns setof public.email_outbox\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  return query\n  with candidates as (\n    select eo.id\n    from public.email_outbox eo\n    where eo.status = 'pending'\n      and eo.scheduled_for <= timezone('utc'::text, now())\n      and (eo.locked_at is null or eo.locked_at < timezone('utc'::text, now()) - interval '10 minutes')\n    order by eo.scheduled_for asc, eo.created_at asc\n    for update skip locked\n    limit greatest(p_limit, 1)\n  ),\n  claimed as (\n    update public.email_outbox eo\n    set\n      status = 'processing',\n      locked_at = timezone('utc'::text, now()),\n      attempt_count = eo.attempt_count + 1\n    where eo.id in (select c.id from candidates c)\n    returning eo.*\n  )\n  select * from claimed;\nend;\n$$;\n\ncreate or replace function public.mark_email_outbox_success(\n  p_id uuid,\n  p_provider_message_id text default null\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  update public.email_outbox\n  set\n    status = 'sent',\n    sent_at = timezone('utc'::text, now()),\n    last_error = null,\n    locked_at = null,\n    provider_message_id = p_provider_message_id,\n    payload = case\n      when event_type = 'employee_created' then payload - 'temp_password'\n      else payload\n    end\n  where id = p_id;\nend;\n$$;\n\ncreate or replace function public.mark_email_outbox_failure(\n  p_id uuid,\n  p_error text\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  update public.email_outbox\n  set\n    status = case\n      when attempt_count >= 4 then 'failed'\n      else 'pending'\n    end,\n    scheduled_for = case\n      when attempt_count >= 4 then timezone('utc'::text, now())\n      when attempt_count = 1 then timezone('utc'::text, now()) + interval '2 minutes'\n      when attempt_count = 2 then timezone('utc'::text, now()) + interval '10 minutes'\n      else timezone('utc'::text, now()) + interval '30 minutes'\n    end,\n    last_error = left(coalesce(p_error, 'Unknown provider error'), 1200),\n    locked_at = null\n  where id = p_id;\nend;\n$$;\n\ncreate extension if not exists pg_net;\n\ndo $$\nbegin\n  if exists (select 1 from cron.job where jobname = 'dispatch_email_outbox_every_minute') then\n    perform cron.unschedule('dispatch_email_outbox_every_minute');\n  end if;\nend\n$$;\n\nselect cron.schedule(\n  'dispatch_email_outbox_every_minute',\n  '* * * * *',\n  $$\n  select\n    net.http_post(\n      url := (select decrypted_secret from vault.decrypted_secrets where name = 'project_url') || '/functions/v1/email-dispatcher',\n      headers := jsonb_build_object(\n        'Content-Type', 'application/json',\n        'Authorization', 'Bearer ' || (select decrypted_secret from vault.decrypted_secrets where name = 'service_role_key')\n      ),\n      body := jsonb_build_object('source', 'pg_cron', 'timestamp', timezone('utc'::text, now())),\n      timeout_milliseconds := 10000\n    );\n  $$\n);"}	email_outbox_and_resend_notifications	rohan5250ssbj@gmail.com	\N	\N
20260221121941	{"-- Resume email notifications and switch dispatcher payload to Brevo.\n\ncreate or replace function public.enqueue_due_task_emails()\nreturns int\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_inserted int := 0;\nbegin\n  with due_candidates as (\n    select\n      t.id as task_id,\n      t.task_name,\n      coalesce(t.description, '') as task_description,\n      coalesce(t.priority, 'medium') as priority,\n      t.due_date,\n      e.id as employee_id,\n      coalesce(e.name, 'Employee') as employee_name,\n      lower(e.email) as recipient_email,\n      concat(\n        'task_due:',\n        t.id::text,\n        ':',\n        e.id::text,\n        ':',\n        extract(epoch from t.due_date)::bigint::text\n      ) as dedupe_key\n    from public.tasks t\n    join public.task_assignments ta on ta.task_id = t.id\n    join public.employees e on e.id = ta.employee_id\n    where t.due_date is not null\n      and t.due_date <= timezone('utc'::text, now())\n      and t.status <> 'completed'\n      and coalesce(e.email, '') <> ''\n  ),\n  inserted as (\n    insert into public.email_outbox (\n      event_type,\n      recipient_email,\n      payload,\n      dedupe_key\n    )\n    select\n      'task_due',\n      due_candidates.recipient_email,\n      jsonb_build_object(\n        'task_id', due_candidates.task_id,\n        'task_name', due_candidates.task_name,\n        'task_description', due_candidates.task_description,\n        'priority', due_candidates.priority,\n        'due_date', due_candidates.due_date,\n        'employee_id', due_candidates.employee_id,\n        'employee_name', due_candidates.employee_name\n      ),\n      due_candidates.dedupe_key\n    from due_candidates\n    on conflict (dedupe_key) do nothing\n    returning 1\n  )\n  select count(*)::int into v_inserted from inserted;\n\n  return coalesce(v_inserted, 0);\nend;\n$$;\n\ndrop trigger if exists trg_task_assignment_email_outbox on public.task_assignments;\ncreate trigger trg_task_assignment_email_outbox\nafter insert on public.task_assignments\nfor each row\nexecute function public.enqueue_task_assignment_email();\n\ndo $$\nbegin\n  if exists (select 1 from cron.job where jobname = 'dispatch_email_outbox_every_minute') then\n    perform cron.unschedule('dispatch_email_outbox_every_minute');\n  end if;\nend\n$$;\n\nselect cron.schedule(\n  'dispatch_email_outbox_every_minute',\n  '* * * * *',\n  $$\n  select\n    net.http_post(\n      url := (select decrypted_secret from vault.decrypted_secrets where name = 'project_url') || '/functions/v1/email-dispatcher',\n      headers := jsonb_build_object(\n        'Content-Type', 'application/json',\n        'Authorization', 'Bearer ' || (select decrypted_secret from vault.decrypted_secrets where name = 'service_role_key')\n      ),\n      body := jsonb_build_object(\n        'source', 'pg_cron',\n        'timestamp', timezone('utc'::text, now()),\n        'email_notifications_enabled', true,\n        'brevo_api_key', (select decrypted_secret from vault.decrypted_secrets where name = 'brevo_api_key'),\n        'brevo_from_email', (select decrypted_secret from vault.decrypted_secrets where name = 'brevo_from_email'),\n        'brevo_from_name', coalesce((select decrypted_secret from vault.decrypted_secrets where name = 'brevo_from_name'), 'TaskFlow'),\n        'app_base_url', coalesce((select decrypted_secret from vault.decrypted_secrets where name = 'app_base_url'), '')\n      ),\n      timeout_milliseconds := 10000\n    );\n  $$\n);"}	resume_email_notifications_brevo	rohan5250ssbj@gmail.com	\N	\N
20260226061251	{"alter table public.task_subtasks\n  add column if not exists assigned_employee_id uuid references public.employees(id) on delete set null;\n\ncreate index if not exists idx_task_subtasks_assigned_employee_id\n  on public.task_subtasks(assigned_employee_id);"}	add_subtask_assignee_support	rohan5250ssbj@gmail.com	\N	\N
20260306091925	{"alter table public.tasks\nadd column if not exists progress_percentage integer not null default 0;\n\nupdate public.tasks\nset progress_percentage = 0\nwhere progress_percentage is null;\n\ndo $$\nbegin\n  if not exists (\n    select 1\n    from pg_constraint\n    where conname = 'tasks_progress_percentage_range'\n  ) then\n    alter table public.tasks\n    add constraint tasks_progress_percentage_range\n    check (progress_percentage >= 0 and progress_percentage <= 100);\n  end if;\nend\n$$;"}	add_task_progress_percentage	rohan5250ssbj@gmail.com	\N	\N
20260306115632	{"-- Realtime direct messages + employee auth bridge\nalter table public.employees\n  add column if not exists auth_user_id uuid references auth.users(id) on delete set null;\n\ncreate unique index if not exists idx_employees_auth_user_id\n  on public.employees(auth_user_id)\n  where auth_user_id is not null;\n\ncreate or replace function public.chat_current_actor_key()\nreturns text\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  uid uuid;\n  employee_uuid uuid;\nbegin\n  uid := auth.uid();\n\n  if uid is null then\n    return null;\n  end if;\n\n  if exists (\n    select 1\n    from public.profiles p\n    where p.id = uid and p.role = 'admin'\n  ) then\n    return 'admin:' || uid::text;\n  end if;\n\n  select e.id into employee_uuid\n  from public.employees e\n  where e.auth_user_id = uid\n  limit 1;\n\n  if employee_uuid is not null then\n    return 'employee:' || employee_uuid::text;\n  end if;\n\n  return null;\nend;\n$$;\n\ngrant execute on function public.chat_current_actor_key() to anon, authenticated, service_role;\n\ncreate table if not exists public.chat_threads (\n  id uuid primary key default gen_random_uuid(),\n  thread_type text not null default 'dm' check (thread_type = 'dm'),\n  participant_a_key text not null,\n  participant_b_key text not null,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  last_message_at timestamptz,\n  constraint chat_threads_dm_pair_order check (participant_a_key < participant_b_key),\n  constraint chat_threads_dm_pair_unique unique (thread_type, participant_a_key, participant_b_key)\n);\n\ncreate index if not exists idx_chat_threads_last_message_at\n  on public.chat_threads(last_message_at desc nulls last, updated_at desc);\n\ncreate table if not exists public.chat_thread_members (\n  thread_id uuid not null references public.chat_threads(id) on delete cascade,\n  member_key text not null,\n  joined_at timestamptz not null default now(),\n  last_read_at timestamptz,\n  primary key (thread_id, member_key)\n);\n\ncreate index if not exists idx_chat_thread_members_member_key\n  on public.chat_thread_members(member_key);\n\ncreate table if not exists public.chat_messages (\n  id uuid primary key default gen_random_uuid(),\n  thread_id uuid not null references public.chat_threads(id) on delete cascade,\n  sender_key text not null,\n  sender_name text not null,\n  sender_avatar_url text,\n  content text not null check (length(btrim(content)) > 0),\n  created_at timestamptz not null default now(),\n  edited_at timestamptz,\n  deleted_at timestamptz\n);\n\ncreate index if not exists idx_chat_messages_thread_created\n  on public.chat_messages(thread_id, created_at desc);\n\ncreate or replace function public.chat_touch_thread_updated_at()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$$;\n\ndrop trigger if exists trg_chat_threads_updated_at on public.chat_threads;\ncreate trigger trg_chat_threads_updated_at\nbefore update on public.chat_threads\nfor each row\nexecute function public.chat_touch_thread_updated_at();\n\ncreate or replace function public.chat_update_thread_last_message()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  update public.chat_threads\n  set last_message_at = new.created_at,\n      updated_at = now()\n  where id = new.thread_id;\n\n  return new;\nend;\n$$;\n\ndrop trigger if exists trg_chat_messages_thread_last_message on public.chat_messages;\ncreate trigger trg_chat_messages_thread_last_message\nafter insert on public.chat_messages\nfor each row\nexecute function public.chat_update_thread_last_message();\n\nalter table public.chat_threads enable row level security;\nalter table public.chat_thread_members enable row level security;\nalter table public.chat_messages enable row level security;\n\ndrop policy if exists \\"chat_threads_select_members\\" on public.chat_threads;\ncreate policy \\"chat_threads_select_members\\"\n  on public.chat_threads\n  for select\n  using (\n    exists (\n      select 1\n      from public.chat_thread_members tm\n      where tm.thread_id = chat_threads.id\n        and tm.member_key = public.chat_current_actor_key()\n    )\n  );\n\ndrop policy if exists \\"chat_thread_members_select_self\\" on public.chat_thread_members;\ncreate policy \\"chat_thread_members_select_self\\"\n  on public.chat_thread_members\n  for select\n  using (\n    member_key = public.chat_current_actor_key()\n  );\n\ndrop policy if exists \\"chat_thread_members_update_self\\" on public.chat_thread_members;\ncreate policy \\"chat_thread_members_update_self\\"\n  on public.chat_thread_members\n  for update\n  using (member_key = public.chat_current_actor_key())\n  with check (member_key = public.chat_current_actor_key());\n\ndrop policy if exists \\"chat_messages_select_members\\" on public.chat_messages;\ncreate policy \\"chat_messages_select_members\\"\n  on public.chat_messages\n  for select\n  using (\n    exists (\n      select 1\n      from public.chat_thread_members tm\n      where tm.thread_id = chat_messages.thread_id\n        and tm.member_key = public.chat_current_actor_key()\n    )\n  );\n\ndrop policy if exists \\"chat_messages_insert_self\\" on public.chat_messages;\ncreate policy \\"chat_messages_insert_self\\"\n  on public.chat_messages\n  for insert\n  with check (\n    sender_key = public.chat_current_actor_key()\n    and exists (\n      select 1\n      from public.chat_thread_members tm\n      where tm.thread_id = chat_messages.thread_id\n        and tm.member_key = public.chat_current_actor_key()\n    )\n  );\n\ndo $$\nbegin\n  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then\n    begin\n      execute 'alter publication supabase_realtime add table public.chat_messages';\n    exception\n      when duplicate_object then\n        null;\n    end;\n  end if;\nend\n$$;"}	realtime_chat_and_auth_bridge	rohan5250ssbj@gmail.com	\N	\N
20260312083105	{"create table if not exists public.task_assignment_activity (\n  id uuid primary key default gen_random_uuid(),\n  task_id uuid not null\n    constraint task_assignment_activity_task_id_fkey\n      references public.tasks(id) on delete cascade,\n  subtask_id uuid null\n    constraint task_assignment_activity_subtask_id_fkey\n      references public.task_subtasks(id) on delete set null,\n  entity_type text not null\n    constraint task_assignment_activity_entity_type_check\n      check (entity_type in ('task', 'subtask')),\n  action text not null\n    constraint task_assignment_activity_action_check\n      check (action in ('assigned', 'reassigned', 'unassigned')),\n  assigned_by_actor_type text not null\n    constraint task_assignment_activity_actor_type_check\n      check (assigned_by_actor_type in ('admin', 'employee')),\n  assigned_by_admin_user_id uuid null\n    constraint task_assignment_activity_assigned_by_admin_user_id_fkey\n      references public.profiles(id) on delete set null,\n  assigned_by_employee_id uuid null\n    constraint task_assignment_activity_assigned_by_employee_id_fkey\n      references public.employees(id) on delete set null,\n  from_employee_id uuid null\n    constraint task_assignment_activity_from_employee_id_fkey\n      references public.employees(id) on delete set null,\n  to_employee_id uuid null\n    constraint task_assignment_activity_to_employee_id_fkey\n      references public.employees(id) on delete set null,\n  created_at timestamptz not null default timezone('utc'::text, now()),\n  constraint task_assignment_activity_entity_subtask_check\n    check (\n      (entity_type = 'task' and subtask_id is null)\n      or (entity_type = 'subtask' and subtask_id is not null)\n    ),\n  constraint task_assignment_activity_actor_identity_check\n    check (\n      (assigned_by_actor_type = 'admin' and assigned_by_admin_user_id is not null and assigned_by_employee_id is null)\n      or (assigned_by_actor_type = 'employee' and assigned_by_employee_id is not null and assigned_by_admin_user_id is null)\n    )\n);\n\ncreate index if not exists idx_task_assignment_activity_task_created_at\n  on public.task_assignment_activity(task_id, created_at desc);\n\ncreate index if not exists idx_task_assignment_activity_subtask_created_at\n  on public.task_assignment_activity(subtask_id, created_at desc);"}	task_assignment_activity	rohan5250ssbj@gmail.com	\N	\N
